// ZW-Pipeline · erzeugt von n8n/bauen.mjs · Version 5b60674794
// Nicht hier ändern: Änderungen im Repo machen und neu bauen.

const SEITE_HTML = "<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>ZW-Station</title>
<style>
:root {
  --bg: #eef1f3; --surface: #ffffff; --surface-2: #f5f7f8; --fg: #16212b; --muted: #5b6b78; --line: #d5dde3;
  --accent: #1f5f8b; --accent-ink: #ffffff; --ok: #1d7a46; --ok-bg: #e3f3e9; --warn: #9a5a00; --warn-bg: #fdf0da;
  --err: #b3261e; --err-bg: #fbe5e3; --info-bg: #e6f0f7;
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-code: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #0f161c; --surface: #172129; --surface-2: #1d2932; --fg: #e6edf2; --muted: #93a4b1; --line: #2c3a45;
    --accent: #6fb3e0; --accent-ink: #0b1720; --ok: #5fd08e; --ok-bg: #143323; --warn: #f0b45a; --warn-bg: #3a2a10;
    --err: #ff8a80; --err-bg: #3d1a18; --info-bg: #16293a; color-scheme: dark;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--fg); font: 16px/1.45 var(--font-ui); padding: 0 16px 48px; }
.wrap { max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; gap: 18px; }
header.bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding-top: 18px; }
.brand { display: flex; align-items: baseline; gap: 10px; }
.brand h1 { font-size: 1.5rem; margin: 0; }
.brand span { color: var(--muted); font-size: .9rem; }
.who { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: .95rem; }
.banner { font-size: .9rem; color: var(--warn); background: var(--warn-bg); padding: 8px 12px; border-radius: 8px; margin: 0; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 22px; display: flex; flex-direction: column; gap: 16px; }
.card h2 { margin: 0; font-size: 1.3rem; }
.hint { color: var(--muted); margin: 0; }
button { font-family: var(--font-ui); cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .5; }
button:focus-visible, input:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn { font-size: 1.05rem; font-weight: 600; padding: 14px 22px; border-radius: 10px; border: 1px solid var(--accent); background: var(--accent); color: var(--accent-ink); min-height: 54px; }
.btn.ghost { background: transparent; color: var(--accent); }
.btn.small { min-height: 40px; padding: 8px 14px; font-size: .95rem; }
.linkbtn { background: none; border: none; color: var(--accent); text-decoration: underline; font-size: .95rem; padding: 6px 0; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field label { font-weight: 500; font-size: .95rem; }
.field input, .search input, textarea { font: 500 1.1rem var(--font-ui); padding: 12px 14px; border-radius: 10px; border: 2px solid var(--line); background: var(--surface-2); color: var(--fg); min-width: 0; }
textarea { font: .85rem var(--font-code); width: 100%; min-height: 90px; }
.search { display: flex; gap: 10px; flex-wrap: wrap; }
.search input { flex: 1 1 220px; font-family: var(--font-code); }
.error { color: var(--err); background: var(--err-bg); padding: 10px 12px; border-radius: 8px; margin: 0; font-weight: 500; }
.list { display: flex; flex-direction: column; gap: 10px; }
.ret { display: grid; grid-template-columns: 1fr auto; gap: 6px 16px; align-items: center; text-align: left; padding: 16px 18px; border-radius: 12px; border: 2px solid var(--line); background: var(--surface-2); color: var(--fg); font-size: 1rem; }
.ret:hover { border-color: var(--accent); }
.ret .nr { font: 600 1.25rem var(--font-code); }
.ret .meta { color: var(--muted); font-size: .9rem; }
.badges { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.badge { font-size: .8rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; background: var(--surface); border: 1px solid var(--line); color: var(--muted); white-space: nowrap; }
.badge.ok { background: var(--ok-bg); color: var(--ok); border-color: transparent; }
.badge.warn { background: var(--warn-bg); color: var(--warn); border-color: transparent; }
.badge.err { background: var(--err-bg); color: var(--err); border-color: transparent; }
.pos { border: 1px solid var(--line); border-radius: 12px; padding: 16px; display: flex; flex-direction: column; gap: 12px; background: var(--surface-2); }
.pos-head { display: grid; grid-template-columns: 64px 1fr; gap: 14px; align-items: start; }
.thumb { width: 64px; aspect-ratio: 1; border-radius: 10px; background: var(--surface); border: 1px solid var(--line); display: grid; place-items: center; color: var(--muted); font-size: .7rem; text-align: center; }
.pos h3 { margin: 0 0 4px; font-size: 1.05rem; overflow-wrap: anywhere; }
.pos .meta { display: flex; flex-wrap: wrap; gap: 4px 14px; color: var(--muted); font-size: .88rem; }
.pos .meta b { font-family: var(--font-code); color: var(--fg); font-weight: 600; }
.cond { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.cond button { min-height: 64px; border-radius: 10px; border: 2px solid var(--line); background: var(--surface); color: var(--fg); font-weight: 600; font-size: .98rem; padding: 8px; }
.cond button:hover { border-color: var(--accent); }
.cond button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.cond button.neg[aria-pressed="true"] { background: var(--muted); border-color: var(--muted); color: var(--surface); }
.preview { border-radius: 10px; padding: 12px 14px; background: var(--info-bg); display: flex; flex-direction: column; gap: 6px; }
.preview .row { display: flex; flex-wrap: wrap; gap: 4px 18px; align-items: baseline; }
.preview .price { font: 700 1.35rem var(--font-code); }
.preview .strike { color: var(--muted); text-decoration: line-through; font-family: var(--font-code); }
.preview .warn { color: var(--warn); background: var(--warn-bg); padding: 6px 10px; border-radius: 8px; font-size: .92rem; }
.preview .info { color: var(--muted); font-size: .88rem; }
.preview.err { background: var(--err-bg); color: var(--err); }
.status { display: flex; align-items: center; gap: 10px; font-weight: 600; padding: 10px 12px; border-radius: 10px; }
.status.wartet { background: var(--warn-bg); color: var(--warn); }
.status.ok { background: var(--ok-bg); color: var(--ok); }
.status.err { background: var(--err-bg); color: var(--err); }
.status.neutral { background: var(--surface); color: var(--muted); border: 1px solid var(--line); }
.status small { font-weight: 400; }
.actions { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.comments { margin: 0; padding-left: 18px; color: var(--muted); font-size: .9rem; }
details.panel { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 4px 20px; }
details.panel > summary { cursor: pointer; padding: 14px 0; font-weight: 600; }
.table-wrap { overflow-x: auto; padding-bottom: 16px; }
table { border-collapse: collapse; width: 100%; font-size: .88rem; font-variant-numeric: tabular-nums; }
th, td { text-align: left; padding: 7px 9px; border-bottom: 1px solid var(--line); white-space: nowrap; }
th { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
td.code { font-family: var(--font-code); }
.setup { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
[hidden] { display: none !important; }
@media (max-width: 640px) {
  /* drei ZW-Zustände in einer Reihe, darunter Nicht verkaufbar und Kein ZW */
  .cond { grid-template-columns: repeat(6, minmax(0, 1fr)); }
  .cond button { grid-column: span 2; padding: 6px 4px; font-size: .92rem; overflow-wrap: anywhere; }
  .cond button.neg { grid-column: span 3; min-height: 52px; }
  .card { padding: 16px; }
}
</style>
</head>
<body>
<div class="wrap">
  <header class="bar">
    <div class="brand"><h1>ZW-Station</h1><span>Lager · Zweite Wahl</span></div>
    <div class="who" id="who" hidden><span id="who-name"></span><button class="btn ghost small" type="button" id="logout">Abmelden</button></div>
  </header>
  <p class="banner" id="banner" hidden>Probelauf mit Beispieldaten: Es wird nichts in plenty oder Shopware geändert.</p>

  <!-- Anmeldung -->
  <section class="card" id="s-login" hidden>
    <h2>Anmelden</h2>
    <form id="login-form" class="list" autocomplete="on">
      <div class="field"><label for="l-user">Benutzername</label><input id="l-user" name="username" autocomplete="username" required autocapitalize="none"></div>
      <div class="field"><label for="l-pass">Passwort</label><input id="l-pass" name="password" type="password" autocomplete="current-password" required></div>
      <p class="error" id="login-error" hidden></p>
      <button class="btn" type="submit" id="login-btn">Anmelden</button>
    </form>
    <button class="linkbtn" type="button" id="open-setup">Zugang einrichten (für Tobias)</button>
  </section>

  <!-- Zugang einrichten: läuft nur im Browser, nichts wird gesendet -->
  <section class="card" id="s-setup" hidden>
    <h2>Zugang einrichten</h2>
    <p class="hint">Erzeugt den Eintrag für eine Person. Das Passwort verlässt diesen Browser nicht. Den Eintrag in n8n im Baustein „Einstellungen“ unter <b>einstellungen.benutzer</b> in die Liste einfügen.</p>
    <form id="setup-form" class="setup">
      <div class="field"><label for="u-user">Benutzername</label><input id="u-user" required autocapitalize="none"></div>
      <div class="field"><label for="u-name">Anzeigename</label><input id="u-name" required></div>
      <div class="field"><label for="u-pass">Passwort (mind. 10 Zeichen)</label><input id="u-pass" type="password" minlength="10" required autocomplete="new-password"></div>
      <div class="field"><label for="u-admin"><input id="u-admin" type="checkbox"> Admin (darf Probelauf zurücksetzen)</label></div>
      <button class="btn" type="submit">Eintrag erzeugen</button>
    </form>
    <textarea id="setup-out" readonly hidden aria-label="Eintrag für die Benutzerliste"></textarea>
    <div class="actions">
      <button class="btn ghost small" type="button" id="gen-secret">Geheimschlüssel erzeugen</button>
      <button class="linkbtn" type="button" id="close-setup">Zurück zur Anmeldung</button>
    </div>
    <textarea id="secret-out" readonly hidden aria-label="Geheimschlüssel"></textarea>
  </section>

  <!-- Retouren-Liste -->
  <section class="card" id="s-list" hidden>
    <h2>Offene Retouren (Status 9.1.1)</h2>
    <form class="search" id="search-form" autocomplete="off">
      <input id="search-input" inputmode="numeric" placeholder="Retouren-Nr." aria-label="Retouren-Nr.">
      <button class="btn" type="submit">Öffnen</button>
    </form>
    <p class="error" id="list-error" hidden></p>
    <div class="list" id="ret-list"></div>
    <p class="hint" id="list-empty" hidden>Keine offenen Retouren.</p>
  </section>

  <!-- Retoure -->
  <section class="card" id="s-ret" hidden>
    <div class="actions">
      <h2 id="ret-title"></h2>
      <button class="linkbtn" type="button" id="back">← Alle Retouren</button>
    </div>
    <p class="hint" id="ret-meta"></p>
    <div class="list" id="pos-list"></div>
    <p class="error" id="ret-error" hidden></p>
    <div class="actions">
      <span class="hint" id="anlegen-hint"></span>
      <button class="btn" type="button" id="anlegen" disabled>Anlegen</button>
    </div>
    <details id="ret-comments-wrap" hidden><summary>Kommentare in der Retoure</summary><ul class="comments" id="ret-comments"></ul></details>
  </section>

  <details class="panel" id="liste-panel" hidden>
    <summary>ZW-Liste und Protokoll</summary>
    <div class="table-wrap">
      <table>
        <thead><tr><th>Datum</th><th>Retoure</th><th>ZW-Variante</th><th>Barcode</th><th>Name</th><th>Zustand</th><th>Preis</th><th>Streichpreis</th><th>neu/+1</th></tr></thead>
        <tbody id="zw-liste"></tbody>
      </table>
    </div>
    <div class="table-wrap">
      <table>
        <thead><tr><th>Zeit</th><th>Wer</th><th>Aktion</th><th>Retoure</th><th>Position</th><th>Zustand</th><th>Ergebnis</th></tr></thead>
        <tbody id="protokoll"></tbody>
      </table>
    </div>
    <div class="actions" id="admin-actions" hidden>
      <span class="hint">Nur Probelauf: Beispieldaten, Protokoll und ZW-Liste auf Anfang setzen.</span>
      <button class="btn ghost small" type="button" id="reset">Probelauf zurücksetzen</button>
    </div>
  </details>
</div>

<script>
(function () {
  'use strict';
  var ZUSTAENDE = ['Neuwertig', 'Sehr gut', 'Gut', 'Nicht verkaufbar', 'Kein ZW'];
  var OHNE_ARTIKEL = ['Nicht verkaufbar', 'Kein ZW'];
  var LEERLAUF_MINUTEN = 30;
  var ABFRAGE_SEKUNDEN = 8;

  // Die Seite liegt unter …/zw-station, die Aktionen unter …/zw-station/<aktion>
  var BASIS = location.pathname.replace(/\/+$/, '') + '/';
  var $ = function (id) { return document.getElementById(id); };
  var eur = new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' });
  var zustand = { schluessel: null, name: '', rolle: '', retoure: null, auswahl: {}, vorschau: {}, abfrage: null, letzteAktivitaet: Date.now() };

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function speichern(k, v) { try { if (v == null) sessionStorage.removeItem(k); else sessionStorage.setItem(k, v); } catch (e) {} }
  function lesen(k) { try { return sessionStorage.getItem(k); } catch (e) { return null; } }

  function zeige(id) {
    ['s-login', 's-setup', 's-list', 's-ret'].forEach(function (s) { $(s).hidden = s !== id; });
    var drin = id === 's-list' || id === 's-ret';
    $('who').hidden = !drin; $('banner').hidden = !drin; $('liste-panel').hidden = !drin;
  }

  function fehler(id, text) { $(id).textContent = text || ''; $(id).hidden = !text; }

  function api(aktion, opt) {
    opt = opt || {};
    var kopf = { 'Accept': 'application/json' };
    if (zustand.schluessel) kopf.Authorization = 'Bearer ' + zustand.schluessel;
    if (opt.body) kopf['Content-Type'] = 'application/json';
    return fetch(BASIS + aktion + (opt.query ? '?' + new URLSearchParams(opt.query) : ''), {
      method: opt.body ? 'POST' : 'GET', headers: kopf, body: opt.body ? JSON.stringify(opt.body) : undefined, cache: 'no-store',
    }).then(function (r) {
      return r.text().then(function (t) {
        var d; try { d = JSON.parse(t); } catch (e) { d = { ok: false, fehler: 'Unerwartete Antwort (' + r.status + ')' }; }
        if (r.status === 401 && aktion !== 'anmelden') { abmelden(d.fehler || 'Bitte neu anmelden.'); throw new Error(d.fehler); }
        if (!r.ok || d.ok === false) throw new Error(d.fehler || ('Fehler ' + r.status));
        return d;
      });
    }, function () { throw new Error('Keine Verbindung zu n8n.'); });
  }

  // ---------- Anmeldung ----------
  $('login-form').addEventListener('submit', function (e) {
    e.preventDefault();
    fehler('login-error');
    $('login-btn').disabled = true;
    api('anmelden', { body: { benutzer: $('l-user').value, passwort: $('l-pass').value } }).then(function (d) {
      zustand.schluessel = d.schluessel; zustand.name = d.name; zustand.rolle = d.rolle;
      speichern('zw-schluessel', d.schluessel); speichern('zw-name', d.name); speichern('zw-rolle', d.rolle);
      $('l-pass').value = '';
      start();
    }).catch(function (err) { fehler('login-error', err.message); }).then(function () { $('login-btn').disabled = false; });
  });

  function abmelden(grund) {
    zustand.schluessel = null; zustand.retoure = null;
    speichern('zw-schluessel', null); speichern('zw-name', null); speichern('zw-rolle', null);
    stoppeAbfrage();
    zeige('s-login');
    fehler('login-error', grund || '');
    setTimeout(function () { $('l-user').focus(); }, 0);
  }
  $('logout').addEventListener('click', function () { abmelden(); });

  ['click', 'keydown', 'touchstart'].forEach(function (t) { document.addEventListener(t, function () { zustand.letzteAktivitaet = Date.now(); }, { passive: true }); });
  setInterval(function () {
    if (zustand.schluessel && Date.now() - zustand.letzteAktivitaet > LEERLAUF_MINUTEN * 60000) abmelden('Automatisch abgemeldet nach ' + LEERLAUF_MINUTEN + ' Minuten ohne Nutzung.');
  }, 30000);

  // ---------- Zugang einrichten (nur im Browser) ----------
  function hex(buf) { return Array.prototype.map.call(new Uint8Array(buf), function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }
  $('open-setup').addEventListener('click', function () { zeige('s-setup'); });
  $('close-setup').addEventListener('click', function () { zeige('s-login'); });
  $('setup-form').addEventListener('submit', function (e) {
    e.preventDefault();
    if (!window.crypto || !crypto.subtle) { alert('Dieser Browser kann hier keinen Hash erzeugen (nur über https).'); return; }
    var durchlaeufe = 10000;
    var salz = crypto.getRandomValues(new Uint8Array(16));
    crypto.subtle.importKey('raw', new TextEncoder().encode($('u-pass').value), 'PBKDF2', false, ['deriveBits']).then(function (k) {
      return crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: salz, iterations: durchlaeufe }, k, 256);
    }).then(function (bits) {
      var eintrag = { benutzer: $('u-user').value.trim().toLowerCase(), name: $('u-name').value.trim(), rolle: $('u-admin').checked ? 'admin' : 'lager',
        hash: 'pbkdf2-sha256$' + durchlaeufe + '$' + hex(salz) + '$' + hex(bits) };
      $('setup-out').value = JSON.stringify(eintrag);
      $('setup-out').hidden = false; $('setup-out').select();
      $('u-pass').value = '';
    });
  });
  $('gen-secret').addEventListener('click', function () {
    $('secret-out').value = hex(crypto.getRandomValues(new Uint8Array(32)));
    $('secret-out').hidden = false; $('secret-out').select();
  });

  // ---------- Retouren ----------
  function start() {
    $('who-name').textContent = zustand.name;
    $('admin-actions').hidden = zustand.rolle !== 'admin';
    ladeListe();
  }

  function ladeListe() {
    stoppeAbfrage();
    zustand.retoure = null;
    zeige('s-list');
    fehler('list-error');
    api('retouren').then(function (d) {
      $('banner').hidden = d.modus !== 'probelauf';
      $('list-empty').hidden = d.retouren.length > 0;
      $('ret-list').innerHTML = d.retouren.map(function (r) {
        var b = [];
        if (r.erledigt) b.push('<span class="badge ok">' + r.erledigt + ' erledigt</span>');
        if (r.wartet) b.push('<span class="badge warn">' + r.wartet + ' wartet</span>');
        if (r.fehler) b.push('<span class="badge err">' + r.fehler + ' Fehler</span>');
        b.push('<span class="badge">' + r.anzahl + (r.anzahl === 1 ? ' Artikel' : ' Artikel') + '</span>');
        return '<button type="button" class="ret" data-nr="' + esc(r.id) + '"><span><span class="nr">' + esc(r.id) + '</span><br><span class="meta">' +
          esc(datum(r.datum)) + ' · ' + esc(r.kunde) + '</span></span><span class="badges">' + b.join('') + '</span></button>';
      }).join('');
      ladeZwListe();
      setTimeout(function () { $('search-input').focus(); }, 0);
    }).catch(function (err) { fehler('list-error', err.message); });
  }
  $('ret-list').addEventListener('click', function (e) {
    var b = e.target.closest('.ret'); if (b) oeffneRetoure(b.dataset.nr);
  });
  $('search-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var nr = $('search-input').value.trim(); if (nr) oeffneRetoure(nr);
  });
  $('back').addEventListener('click', ladeListe);

  function datum(iso) { if (!iso) return ''; var t = String(iso).slice(0, 10).split('-'); return t.length === 3 ? t[2] + '.' + t[1] + '.' + t[0] : iso; }

  function oeffneRetoure(nr) {
    fehler('list-error');
    api('retoure', { query: { nr: nr } }).then(function (d) {
      zustand.auswahl = {}; zustand.vorschau = {};
      zustand.retoure = d.retoure;
      $('search-input').value = '';
      zeige('s-ret');
      zeigeRetoure();
    }).catch(function (err) { fehler('list-error', err.message); });
  }

  function offen(p) { return p.status === 'offen' || p.status === 'abgelehnt' || p.status === 'fehler'; }

  function zeigeRetoure() {
    var r = zustand.retoure;
    $('ret-title').textContent = 'Retoure ' + r.id;
    $('ret-meta').textContent = datum(r.datum) + ' · ' + r.kunde + ' · Auftrag ' + r.auftragId + ' · Status ' + r.status;
    $('pos-list').innerHTML = r.positionen.map(positionHtml).join('');
    $('ret-comments-wrap').hidden = !r.kommentare.length;
    $('ret-comments').innerHTML = r.kommentare.map(function (k) { return '<li>' + esc(k.text) + '</li>'; }).join('');
    aktualisiereAnlegen();
    if (r.positionen.some(function (p) { return p.status === 'wartet'; })) starteAbfrage(); else stoppeAbfrage();
  }

  function positionHtml(p) {
    var kopf = '<div class="pos-head"><div class="thumb">' + (p.bild ? '<img src="' + esc(p.bild) + '" alt="">' : 'Kein Bild') + '</div><div><h3>' + esc(p.name) + '</h3>' +
      '<div class="meta"><span>EAN <b>' + esc(p.ean || '–') + '</b></span><span>Variante <b>' + esc(p.varianteId) + '</b></span></div>' +
